extern vec4 u_frameUV;
extern vec2 u_framePx;
extern number u_u;
extern number u_alpha;

number colorNear(vec3 a, vec3 b)
{
  vec3 d = abs(a - b);
  return step(max(max(d.r, d.g), d.b), 0.055);
}

vec4 effect(vec4 color, Image tex, vec2 texCoord, vec2 screenCoord)
{
  vec4 base = Texel(tex, texCoord);
  if (base.a < 0.08) {
    discard;
  }

  vec3 c = base.rgb;
  number sawMask = max(colorNear(c, vec3(0.145, 0.137, 0.133)),
    max(colorNear(c, vec3(0.545, 0.671, 0.765)), colorNear(c, vec3(0.702, 0.827, 0.855))));
  if (sawMask < 0.5) {
    discard;
  }

  vec2 localUv = (texCoord - u_frameUV.xy) / max(u_frameUV.zw, vec2(0.0001));
  vec2 pix = floor(localUv * u_framePx);
  number flickerSeed = fract(sin(dot(pix + floor(u_u * 18.0), vec2(12.9898, 78.233))) * 43758.5453);
  number stripe = step(0.50, fract((pix.x + pix.y * 0.6) * 0.23 + u_u * 9.0));
  number spark = step(0.86, flickerSeed);
  number pulse = 0.55 + 0.45 * step(0.5, fract(u_u * 14.0));
  number lit = clamp((stripe * 0.45 + spark * 0.85) * pulse, 0.0, 1.0);
  vec3 yellow = vec3(0.969, 0.969, 0.341);
  vec3 white = vec3(1.0, 1.0, 1.0);
  vec3 outCol = mix(yellow, white, spark * 0.75);
  return vec4(outCol, clamp((0.55 + lit * 0.45) * u_alpha, 0.0, 1.0) * base.a) * color;
}

extern vec4 u_frameUV;
extern vec2 u_framePx;
extern number u_u;
extern number u_alpha;
extern vec3 u_color;

vec4 effect(vec4 color, Image tex, vec2 texCoord, vec2 screenCoord)
{
  vec4 base = Texel(tex, texCoord);
  if (base.a < 0.08) {
    discard;
  }

  vec2 localUv = (texCoord - u_frameUV.xy) / max(u_frameUV.zw, vec2(0.0001));
  vec2 pix = floor(localUv * u_framePx);
  number sweep = fract(localUv.y * 3.0 + u_u * 2.2);
  number band = smoothstep(0.00, 0.12, sweep) * (1.0 - smoothstep(0.18, 0.34, sweep));
  number sparkleSeed = fract(sin(dot(pix + floor(u_u * 16.0), vec2(12.9898, 78.233))) * 43758.5453);
  number sparkle = step(0.965, sparkleSeed) * smoothstep(0.10, 0.55, localUv.y) * (1.0 - smoothstep(0.98, 1.0, localUv.y));
  number edgePulse = step(0.88, fract((pix.x + pix.y) * 0.25 - u_u * 5.0)) * 0.12;
  number a = clamp((band * 0.55 + sparkle * 0.85 + edgePulse) * u_alpha, 0.0, 0.9) * base.a;
  vec3 col = mix(u_color, vec3(0.95, 1.0, 0.45), sparkle * 0.75);
  return vec4(col, a) * color;
}

extern number u_time;
extern number u_intensity;
extern vec4 u_frameUV;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 src = Texel(tex, tc);
  if (src.a <= 0.001) return vec4(0.0);

  vec2 uv = (tc - u_frameUV.xy) / max(u_frameUV.zw, vec2(0.00001));
  float swayA = 0.5 + 0.5 * sin(uv.x * 21.0 + u_time * 5.1
    + sin(uv.y * 13.0 - u_time * 3.4) * 1.35);
  float swayB = 0.5 + 0.5 * sin(uv.x * 37.0 - u_time * 4.2
    + sin(uv.y * 19.0 + u_time * 2.7));
  float flow = fract(uv.y * 1.75 + u_time * 0.92
    + (swayA - 0.5) * 0.20 + (swayB - 0.5) * 0.09);
  float riseBand = smoothstep(0.82, 0.34, flow) * smoothstep(0.03, 0.20, flow);
  float tongue = smoothstep(0.36, 0.78, swayA * 0.68 + swayB * 0.32);
  float flicker = 0.82 + 0.18 * sin(u_time * 11.0 + uv.x * 15.0 - uv.y * 9.0);
  float heat = clamp(0.18 + riseBand * (0.48 + 0.52 * tongue), 0.0, 1.0) * flicker;

  vec3 ember = vec3(0.78, 0.055, 0.012);
  vec3 orange = vec3(1.00, 0.27, 0.025);
  vec3 gold = vec3(1.00, 0.80, 0.16);
  vec3 flame = mix(ember, orange, smoothstep(0.20, 0.62, heat));
  flame = mix(flame, gold, smoothstep(0.62, 0.94, heat));
  float luminance = dot(src.rgb, vec3(0.299, 0.587, 0.114));
  flame = mix(flame, flame * (0.72 + luminance * 0.42), 0.34);

  float overlayAlpha = src.a * color.a * u_intensity * (0.30 + heat * 0.58);
  return vec4(flame, overlayAlpha);
}

extern vec2 u_texel;
extern vec2 u_uvMin;
extern vec2 u_uvMax;
extern number u_alpha;
extern number u_time;
extern number u_hit;
extern number u_hitSide;

float spriteAlpha(Image tex, vec2 uv) {
  if (uv.x < u_uvMin.x || uv.y < u_uvMin.y
      || uv.x >= u_uvMax.x || uv.y >= u_uvMax.y) return 0.0;
  return Texel(tex, uv).a;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float a0 = spriteAlpha(tex, tc);
  vec2 s = u_texel;
  float l = spriteAlpha(tex, tc + vec2(-s.x, 0.0));
  float r = spriteAlpha(tex, tc + vec2( s.x, 0.0));
  float u = spriteAlpha(tex, tc + vec2(0.0, -s.y));
  float d = spriteAlpha(tex, tc + vec2(0.0,  s.y));
  float n1 = max(max(l, r), max(u, d));
  n1 = max(n1, max(
    max(spriteAlpha(tex, tc + vec2(-s.x, -s.y)),
        spriteAlpha(tex, tc + vec2( s.x, -s.y))),
    max(spriteAlpha(tex, tc + vec2(-s.x,  s.y)),
        spriteAlpha(tex, tc + vec2( s.x,  s.y)))));
  float pulse = 0.5 + 0.5 * sin(u_time * 2.7);
  if (a0 <= 0.01) {
    if (n1 > 0.01)
      return vec4(mix(vec3(0.39, 0.82, 0.84), vec3(0.92, 0.98, 1.00), u_hit),
        n1 * u_alpha * (0.42 + pulse * 0.10 + u_hit * 0.34));
    return vec4(0.0);
  }

  vec2 frameSize = max(u_uvMax - u_uvMin, vec2(0.00001));
  vec2 localUv = (tc - u_uvMin) / frameSize;
  float edge = 1.0 - min(min(l, r), min(u, d));
  float sweepCenter = mod(u_time * 0.19, 1.55) - 0.25;
  float sweepDistance = abs(localUv.x + localUv.y * 0.32 - sweepCenter);
  float sweep = 1.0 - smoothstep(0.035, 0.105, sweepDistance);
  float impactX = mix(0.20, 0.80, step(0.0, u_hitSide));
  float impactZone = 1.0 - smoothstep(0.08, 0.48, abs(localUv.x - impactX));
  float impactLine = 1.0 - smoothstep(0.025, 0.085,
    abs((localUv.y - 0.46) + (localUv.x - impactX) * 0.55));
  float steelHit = u_hit * (0.42 + impactZone * 0.58);
  vec3 shieldColor = mix(vec3(0.10, 0.42, 0.47),
    vec3(0.76, 1.00, 1.00), clamp(edge * 0.62 + sweep, 0.0, 1.0));
  shieldColor = mix(shieldColor, vec3(0.93, 0.98, 1.00),
    clamp(steelHit + impactLine * u_hit * 0.42, 0.0, 1.0));
  float shieldAlpha = a0 * u_alpha
    * (0.075 + edge * 0.11 + sweep * 0.12 + pulse * 0.02
      + steelHit * 0.36 + impactLine * u_hit * 0.16);
  return vec4(shieldColor, shieldAlpha);
}

  extern number u_strength;      // judgement global strength (0..1)
  extern vec3 u_dark;            // dark red
  extern vec3 u_mid;             // mid red
  extern vec3 u_light;           // light red/pink
extern number u_strengthMul;   // extra multiplier from config
extern number u_mixKeep;       // fraction of original color to keep (post gradient)
extern number u_blueCut;       // how strongly to suppress residual blue/cyan components
  vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
    vec4 src = Texel(tex, tc) * color;
    if (src.a < 0.001) return vec4(0.0);
float str = clamp(u_strength * u_strengthMul, 0.0, 1.0);
if (str <= 0.0001) return src; // no change if inactive
    // Use luminance of original pixel to choose gradient position
    float lum = dot(src.rgb, vec3(0.299,0.587,0.114));
    // Three-point gradient: dark -> mid -> light (piecewise blend)
    vec3 target;
    if (lum < 0.5){
      float t = lum / 0.5; // 0..1
      target = mix(u_dark, u_mid, t);
    } else {
      float t = (lum - 0.5) / 0.5; // 0..1
      target = mix(u_mid, u_light, t);
    }
    // Preserve subtle details by partial mix with original based on strength
    // First blend strongly toward target (linear strength for smooth transition)
    vec3 outRGB = mix(src.rgb, target, clamp(str, 0.0, 1.0));
    // Suppress remaining blue/cyan so 하늘색 느낌 제거
    float cut = u_blueCut * str;
    outRGB.b = outRGB.b * (1.0 - 0.85 * cut);
    // Cyan suppression: if G is notably higher than R, pull it slightly toward R
    float cy = max(0.0, (outRGB.g - outRGB.r));
    outRGB.g -= cy * 0.55 * cut;
    // Slight additional red push for near-horizon bright pixels
    float horizonBoost = smoothstep(0.55, 0.95, lum) * (0.10 * str);
    outRGB.r = clamp(outRGB.r + horizonBoost, 0.0, 1.0);
    // Reintroduce tiny portion of original to avoid flat banding
    float keep = clamp(u_mixKeep, 0.0, 1.0);
    outRGB = mix(outRGB, src.rgb, keep * (1.0 - str));
    return vec4(outRGB, src.a);
  }

  extern number u_strength;    // global fade 0..1
  extern number u_weight;      // per-layer intensity weight 0..1
  extern number u_targetHue;   // 0..1 hue target (red moon ~0.0 or slightly shifted)
  extern number u_hueBlend;    // how strongly to move hue toward target
  extern number u_satGain;     // additive saturation gain scaled by strength
  extern number u_valDarken;   // darken factor for shadows
extern number u_highlightPreserve; // 0..1 preserve highlight brightness
extern number u_greenGuard;  // reduce shift on pure greens (0..1)
extern number u_redBias;     // extra red lift for midtones (0..1)
extern vec3  u_fogColor;     // red fog color
extern number u_fogAmt;      // 0..1 fog blending amount
extern number u_desat;       // 0..1 desaturate non-red hues

extern number u_poisonStrength;
extern number u_chillStrength;
extern number u_grayscale;
extern bool u_ts_active;
extern vec2 u_ts_center;
extern number u_ts_radius;
extern number u_ts_softness;

  vec3 rgb2hsv(vec3 c){
    float maxc = max(c.r, max(c.g, c.b));
    float minc = min(c.r, min(c.g, c.b));
    float delta = maxc - minc;
    float h = 0.0;
    if (delta > 1e-5){
      if (maxc == c.r){ h = mod((c.g - c.b) / delta, 6.0); }
      else if (maxc == c.g){ h = ((c.b - c.r) / delta) + 2.0; }
      else { h = ((c.r - c.g) / delta) + 4.0; }
      h /= 6.0;
      if (h < 0.0) h += 1.0;
    }
    float s = (maxc <= 0.0) ? 0.0 : (delta / maxc);
    float v = maxc;
    return vec3(h,s,v);
  }
  vec3 hsv2rgb(vec3 h){
    float H = h.x * 6.0;
    float C = h.z * h.y;
    float X = C * (1.0 - abs(mod(H,2.0)-1.0));
    vec3 rgb = vec3(0.0);
    if (0.0 <= H && H < 1.0) rgb = vec3(C,X,0.0);
    else if (1.0 <= H && H < 2.0) rgb = vec3(X,C,0.0);
    else if (2.0 <= H && H < 3.0) rgb = vec3(0.0,C,X);
    else if (3.0 <= H && H < 4.0) rgb = vec3(0.0,X,C);
    else if (4.0 <= H && H < 5.0) rgb = vec3(X,0.0,C);
    else if (5.0 <= H && H < 6.0) rgb = vec3(C,0.0,X);
    float m = h.z - C;
    return rgb + m;
  }
  vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
    vec4 src = Texel(tex, tc) * color;
    if (src.a < 0.001) return vec4(0.0);
    float strength = u_strength * u_weight;
    vec3 outRGB = src.rgb;
    if (strength > 0.0001) {
      vec3 hsv = rgb2hsv(src.rgb);
      // Guard greens: reduce hue shift for strong green midtones to prevent unnatural magenta
      float greenness = clamp(src.g - max(src.r, src.b), 0.0, 1.0); // >0 if g dominates
      float guard = mix(1.0, 1.0 - u_greenGuard, greenness);
      // Shift hue toward target
      float hueDiff = u_targetHue - hsv.x;
      // wrap shortest path
      if (hueDiff > 0.5) hueDiff -= 1.0; else if (hueDiff < -0.5) hueDiff += 1.0;
      hsv.x += hueDiff * u_hueBlend * strength * guard;
      if (hsv.x < 0.0) hsv.x += 1.0; else if (hsv.x > 1.0) hsv.x -= 1.0;
      // Saturation shaping: boost slightly, but desaturate hues far from target (prevents harsh greens/blues)
      // angular distance in hue space (wrapped)
      float diff = u_targetHue - hsv.x;
      if (diff > 0.5) diff -= 1.0; else if (diff < -0.5) diff += 1.0;
      float ad = abs(diff);
      // k near 1.0 for colors far from red, 0.0 for near red
      float k = smoothstep(0.12, 0.38, ad);
      float desatAmt = u_desat * strength * k;
      hsv.y = clamp(hsv.y + u_satGain * strength - desatAmt, 0.0, 1.0);
      // Avoid contrast boost: minimal value shaping, preserve highlights strongly
      float preserve = smoothstep(0.0, 1.0, hsv.z);
      // tiny lift toward mid to prevent crushed shadows (reduces contrast)
      float lift = 0.03 * strength * (1.0 - preserve * u_highlightPreserve);
      hsv.z = clamp(mix(hsv.z, 0.6, lift), 0.0, 1.0);
      outRGB = hsv2rgb(hsv);
      // Add slight red grade to midtones to ensure perceptible "red moon" feel
      float lumaOut = dot(outRGB, vec3(0.299, 0.587, 0.114));
      float redLift = u_redBias * strength * smoothstep(0.15, 0.85, 1.0 - lumaOut);
      outRGB.r = clamp(outRGB.r + redLift, 0.0, 1.0);
      // Red fog blend to lower contrast and unify palette
      float fogF = u_fogAmt * strength;
      outRGB = mix(outRGB, u_fogColor, fogF);
      // Keep some original detail, but lighter mix to avoid washing out the tint
      float detailMix = 0.06 * strength;
      outRGB = mix(outRGB, src.rgb, detailMix);
    }

    // Poison Tint (Sickly Muddy Green)
    if (u_poisonStrength > 0.001) {
      vec3 sicklyGreen = vec3(0.22, 0.42, 0.10);
      vec3 multiplied = outRGB * sicklyGreen * 1.5;
      outRGB = mix(outRGB, multiplied, u_poisonStrength * 0.85);
      outRGB.g += u_poisonStrength * 0.06;
    }

    // Chill Tint (Blue Filter)
    if (u_chillStrength > 0.001) {
      vec3 chillColor = vec3(0.1, 0.35, 1.0);
      vec3 tinted = outRGB * chillColor * 2.1;
      outRGB = mix(outRGB, tinted, u_chillStrength * 0.7);
    }

    // Time Stop Grayscale (Radial Wave)
    float tsMask = 1.0;
    if (u_ts_active) {
      float dist = distance(sc, u_ts_center);
      float edge = smoothstep(u_ts_radius, u_ts_radius + u_ts_softness, dist);
      tsMask = 1.0 - edge;
    }
    float grayAmt = u_grayscale * tsMask;
    if (grayAmt > 0.001) {
      float gray = dot(outRGB, vec3(0.299, 0.587, 0.114));
      outRGB = mix(outRGB, vec3(gray), grayAmt);
    }

    return vec4(outRGB, src.a);
  }

extern number u_blend;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc);
  if (px.a <= 0.05) discard;
  vec3 rgb = floor(px.rgb * 255.0 + 0.5);
  bool hit0 = all(equal(rgb, vec3(32.0, 152.0, 48.0)));
  bool hit1 = all(equal(rgb, vec3(24.0, 104.0, 32.0)));
  if (!(hit0 || hit1)) discard;
  vec3 rage = vec3(0.86, 0.12, 0.08);
  if (hit1) {
    rage = vec3(0.50, 0.05, 0.06);
  }
  vec3 outColor = mix(px.rgb, rage, clamp(u_blend, 0.0, 1.0));
  return vec4(outColor, px.a * clamp(u_blend, 0.0, 1.0)) * color;
}

extern vec3 u_target;
extern vec3 u_flash;
extern number u_alpha;
extern number u_tolerance;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc);
  if (px.a <= 0.05) discard;
  float d = distance(px.rgb, u_target);
  if (d > u_tolerance) discard;
  float edge = 1.0 - smoothstep(u_tolerance * 0.45, u_tolerance, d);
  vec3 outColor = mix(px.rgb, u_flash, 0.86);
  return vec4(outColor, px.a * u_alpha * edge) * color;
}

extern number u_alpha;
extern vec3 u_color;
extern vec3 u_palette0;
extern vec3 u_palette1;
extern vec3 u_palette2;
extern vec3 u_palette3;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc);
  if (px.a <= 0.05) discard;
  vec3 rgb = floor(px.rgb * 255.0 + 0.5);
  vec3 p0 = floor(u_palette0 * 255.0 + 0.5);
  vec3 p1 = floor(u_palette1 * 255.0 + 0.5);
  vec3 p2 = floor(u_palette2 * 255.0 + 0.5);
  vec3 p3 = floor(u_palette3 * 255.0 + 0.5);
  bool hit0 = all(equal(rgb, p0));
  bool hit1 = all(equal(rgb, p1));
  bool hit2 = all(equal(rgb, p2));
  bool hit3 = all(equal(rgb, p3));
  if (!(hit0 || hit1 || hit2 || hit3)) discard;
  return vec4(u_color, px.a * u_alpha) * color;
}

extern number u_time;   // seconds
extern number u_freq;   // Hz
extern vec3  u_base;    // base dark-gold
extern vec3  u_peak;    // peak gold
extern number u_lumaThresh; // luminance threshold (0..1, pixels darker than this get recolored)
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec4 px = Texel(tex, tc) * color;
  if (px.a <= 0.001) return vec4(0.0);
  // Calculate luminance (perceived brightness)
  float luma = dot(px.rgb, vec3(0.299, 0.587, 0.114));
  // Only recolor very dark pixels (outline), keep bright pixels (eyes, highlights) unchanged
  if (luma < u_lumaThresh) {
    float s = 0.5 + 0.5 * sin(6.2831853 * u_freq * u_time);
    // Stronger pulse: blend from base to peak more aggressively
    vec3 gold = mix(u_base, u_peak, s * 0.85);
    return vec4(gold, px.a);
  }
  return px;
}

extern number u_yTop;   // screen-space top Y of sprite
extern number u_yBot;   // screen-space bottom Y of sprite
extern number u_pos;    // 0..1 sweep progress (0 bottom -> 1 top)
extern number u_band;   // band thickness as fraction of sprite height (e.g., 0.25)
extern vec3   u_color;  // glow color
extern number u_alpha;  // overall intensity multiplier
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc) * color;
  if (px.a <= 0.001) return vec4(0.0);
  float top = float(u_yTop);
  float bot = float(u_yBot);
  float h = max(1.0, bot - top);
  // Center of band, moving bottom -> top
  float cy = bot - clamp(u_pos, 0.0, 1.0) * h;
  float dy = abs(sc.y - cy);
  float halfW = max(1.0, h * clamp(u_band, 0.02, 1.0) * 0.5);
  // Soft profile: 1 at center, fades to 0 at |dy|>=halfW
  float t = clamp(1.0 - dy / halfW, 0.0, 1.0);
  // Sharpen the peak slightly
  float glow = pow(t, 1.5);
  // Multiply by source alpha so only sprite area glows
  float a = glow * px.a * clamp(u_alpha, 0.0, 2.0);
  return vec4(u_color * a, a);
}

extern vec4 u_frameUV;   // minU, minV, sizeU, sizeV
extern vec4 u_color;     // rgb + base alpha
extern float u_time;
extern float u_alphaThr;
extern vec2 u_grid;
extern float u_starSize;

float sampleA(Image tex, vec2 tc) {
  vec2 uvMin = u_frameUV.xy;
  vec2 uvMax = u_frameUV.xy + u_frameUV.zw;
  vec2 pad = vec2(0.00001);
  vec2 c = clamp(tc, uvMin + pad, uvMax - pad);
  return Texel(tex, c).a;
}

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float starMask(vec2 p, float size) {
  vec2 q = abs(p / max(0.0001, size));
  float r = length(q);
  float core = exp(-r * 12.0);
  float thick = 0.025;
  float decay = 8.0;
  float armH = smoothstep(thick, 0.0, q.y) * exp(-q.x * decay);
  float armV = smoothstep(thick, 0.0, q.x) * exp(-q.y * decay);
  return clamp(core + (armH + armV) * 2.0, 0.0, 1.0);
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float spriteAlpha = sampleA(tex, tc);

  vec2 uvMin = u_frameUV.xy;
  vec2 uvSize = max(u_frameUV.zw, vec2(0.00001));
  vec2 uv = (tc - uvMin) / uvSize; // 0..1

  // 1. Golden Sweep (Sheen)
  float sweepSpeed = 0.8;
  float sweepT = fract(u_time * sweepSpeed);
  float sweepPos = -0.5 + sweepT * 2.0; // -0.5 to 1.5
  float sweepDist = abs((uv.x + uv.y) * 0.5 - sweepPos);
  float sweep = smoothstep(0.15, 0.0, sweepDist) * 0.6;
  sweep *= spriteAlpha; // Mask sweep to sprite shape

  // 2. Sparkles
  vec2 cell = uv * u_grid;
  vec2 g = floor(cell);
  float totalSparkle = 0.0;

  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 currentG = g + neighbor;

      float jx = hash21(currentG + vec2(3.1, 7.7)) - 0.5;
      float jy = hash21(currentG + vec2(9.2, 2.4)) - 0.5;
      vec2 offset = vec2(jx, jy) * 0.4;

      vec2 cellCenterUV = uvMin + ( (currentG + 0.5 + offset) / u_grid ) * uvSize;
      float anchor = sampleA(tex, cellCenterUV);

      if (anchor > u_alphaThr) {
        float r = hash21(currentG);
        float pick = smoothstep(0.75, 0.98, r); // Fewer, but brighter stars

        if (pick > 0.0) {
           float phase = u_time * (2.0 + 1.5 * r) + r * 24.0;
           float s = sin(phase) * 0.5 + 0.5;
           float blink = smoothstep(0.5, 0.98, s);
           blink = blink * blink;

           vec2 f = fract(cell) - neighbor - 0.5 - offset;
           float size = u_starSize * (0.8 + 0.6 * r);
           float flare = starMask(f, size);

           totalSparkle += pick * blink * flare;
        }
      }
    }
  }

  // Combine
  float intensity = sweep + totalSparkle * 3.0;

  // Apply color
  return vec4(u_color.rgb, u_color.a * intensity);
}

vec3 replaceNear(vec3 rgb, vec3 src, vec3 dst, float tolerance) {
  float d = distance(rgb, src);
  float m = 1.0 - smoothstep(tolerance * 0.45, tolerance, d);
  return mix(rgb, dst, m);
}

vec3 replaceGazerLaserRed(vec3 rgb) {
  float redDominance = rgb.r - max(rgb.g, rgb.b);
  float hotRed = smoothstep(0.22, 0.42, redDominance) * smoothstep(0.30, 0.78, rgb.r);
  float lowBlue = 1.0 - smoothstep(0.08, 0.22, rgb.b);
  float laserMask = hotRed * lowBlue * (1.0 - smoothstep(0.55, 0.82, rgb.g));
  float v = max(rgb.r, max(rgb.g, rgb.b));
  vec3 yellowDark = vec3(0.72, 0.45, 0.00);
  vec3 yellowMid = vec3(1.00, 0.74, 0.02);
  vec3 yellowHot = vec3(1.00, 0.92, 0.28);
  vec3 yellow = mix(yellowDark, yellowMid, smoothstep(0.35, 0.70, v));
  yellow = mix(yellow, yellowHot, smoothstep(0.70, 0.95, v));
  return mix(rgb, yellow, laserMask);
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc);
  if (px.a < 0.01) return vec4(0.0);
  vec3 rgb = px.rgb;
  float tol = 2.5 / 255.0;

  // Gazer attack laser reds -> persistent gaze yellows.
  rgb = replaceNear(rgb, vec3(0.564706, 0.062745, 0.000000), vec3(0.721569, 0.454902, 0.000000), tol);
  rgb = replaceNear(rgb, vec3(0.874510, 0.372549, 0.341176), vec3(1.000000, 0.878431, 0.341176), tol);
  rgb = replaceNear(rgb, vec3(0.654902, 0.278431, 0.247059), vec3(0.909804, 0.705882, 0.145098), tol);
  rgb = replaceNear(rgb, vec3(0.815686, 0.062745, 0.000000), vec3(1.000000, 0.784314, 0.000000), tol);
  rgb = replaceGazerLaserRed(rgb);

  return vec4(rgb, px.a) * color;
}

extern vec4 glowColor;
vec4 effect(vec4 color, Image texture, vec2 texture_coords, vec2 screen_coords) {
    vec2 uv = (texture_coords - 0.5) * 2.0; // range [-1.0, 1.0]
    float dist = length(uv);
    // Map [0, 1] to [1, 0] with a soft natural curve
    float alpha = clamp(1.0 - dist, 0.0, 1.0);
    // User requested bright center and natural fade
    alpha = pow(alpha, 1.4);
    return glowColor * alpha;
}

extern vec2 texelStep;      // texture coord offset equal to 1 screen pixel
extern vec4 outlineColor;   // RGBA
extern float threshold;     // alpha threshold
extern float radiusPx;      // outline radius in px (1.0 to 2.0 for sub-pixel logic)
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a0 = Texel(tex, tc).a;
  if (a0 <= threshold){
    vec2 s = texelStep;

    // Layer 1: Immediate cardinal neighbors (1px) -> Always Solid
    float aL = Texel(tex, tc + vec2(-s.x, 0.0)).a;
    float aR = Texel(tex, tc + vec2( s.x, 0.0)).a;
    float aU = Texel(tex, tc + vec2(0.0, -s.y)).a;
    float aD = Texel(tex, tc + vec2(0.0,  s.y)).a;

    if (max(max(aL, aR), max(aU, aD)) > threshold) {
        return outlineColor;
    }

    // Layer 2: Sub-pixel extension (Hard Cut)
    // If radius is 1.15, we draw 15% of the 2nd pixel layer solid, then cut off.
    if (radiusPx > 1.0) {
        float extra = radiusPx - 1.0;
        vec2 pos = tc / texelStep;
        vec2 f = fract(pos); // 0..1 within current texel

        // Left-Left Source (Expanding Right)
        float aLL = Texel(tex, tc + vec2(-s.x * 2.0, 0.0)).a;
        if (aLL > threshold && f.x < extra) return outlineColor;

        // Right-Right Source (Expanding Left)
        float aRR = Texel(tex, tc + vec2( s.x * 2.0, 0.0)).a;
        if (aRR > threshold && f.x > (1.0 - extra)) return outlineColor;

        // Up-Up Source (Expanding Down)
        float aUU = Texel(tex, tc + vec2(0.0, -s.y * 2.0)).a;
        if (aUU > threshold && f.y < extra) return outlineColor;

        // Down-Down Source (Expanding Up)
        float aDD = Texel(tex, tc + vec2(0.0,  s.y * 2.0)).a;
        if (aDD > threshold && f.y > (1.0 - extra)) return outlineColor;
    }
  }
  return vec4(0.0);
}

extern vec2 texelStep;      // texture coord offset equal to 1 screen pixel
extern vec4 outlineColor;   // RGBA
extern float threshold;     // alpha threshold
extern float radiusPx;      // outline radius in px (1=1px)
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a0 = Texel(tex, tc).a;
  if (a0 <= threshold){
    vec2 s = texelStep;
    float a1 = Texel(tex, tc + vec2( s.x, 0.0)).a;
    float a2 = Texel(tex, tc + vec2(-s.x, 0.0)).a;
    float a3 = Texel(tex, tc + vec2(0.0,  s.y)).a;
    float a4 = Texel(tex, tc + vec2(0.0, -s.y)).a;
    float a5 = Texel(tex, tc + vec2( s.x,  s.y)).a;
    float a6 = Texel(tex, tc + vec2(-s.x, -s.y)).a;
    float a7 = Texel(tex, tc + vec2( s.x, -s.y)).a;
    float a8 = Texel(tex, tc + vec2(-s.x,  s.y)).a;
    float neighbor = max(max(max(a1,a2),max(a3,a4)), max(max(a5,a6),max(a7,a8)));
    if (radiusPx > 1.5){
      vec2 t = s * 2.0;
      float b1 = Texel(tex, tc + vec2( t.x, 0.0)).a;
      float b2 = Texel(tex, tc + vec2(-t.x, 0.0)).a;
      float b3 = Texel(tex, tc + vec2(0.0,  t.y)).a;
      float b4 = Texel(tex, tc + vec2(0.0, -t.y)).a;
      float b5 = Texel(tex, tc + vec2( t.x,  t.y)).a;
      float b6 = Texel(tex, tc + vec2(-t.x, -t.y)).a;
      float b7 = Texel(tex, tc + vec2( t.x, -t.y)).a;
      float b8 = Texel(tex, tc + vec2(-t.x,  t.y)).a;
      float neighbor2 = max(max(max(b1,b2),max(b3,b4)), max(max(b5,b6),max(b7,b8)));
      neighbor = max(neighbor, neighbor2);
    }
    if (radiusPx > 2.5){
      vec2 t = s * 3.0;
      float c1 = Texel(tex, tc + vec2( t.x, 0.0)).a;
      float c2 = Texel(tex, tc + vec2(-t.x, 0.0)).a;
      float c3 = Texel(tex, tc + vec2(0.0,  t.y)).a;
      float c4 = Texel(tex, tc + vec2(0.0, -t.y)).a;
      float c5 = Texel(tex, tc + vec2( t.x,  t.y)).a;
      float c6 = Texel(tex, tc + vec2(-t.x, -t.y)).a;
      float c7 = Texel(tex, tc + vec2( t.x, -t.y)).a;
      float c8 = Texel(tex, tc + vec2(-t.x,  t.y)).a;
      float neighbor3 = max(max(max(c1,c2),max(c3,c4)), max(max(c5,c6),max(c7,c8)));
      neighbor = max(neighbor, neighbor3);
    }
    if (neighbor > threshold){ return outlineColor; }
  }
  return vec4(0.0);
}

extern number u_time;   // seconds
extern number u_alpha;  // overlay opacity
extern number u_speed;  // cycles per second
extern number u_scale;  // spatial scale of stripes
extern vec2 u_dir;      // normalized direction of motion/gradient
vec3 rainbow(float x){
  // Smooth rainbow via phase-shifted cosines
  return 0.5 + 0.5 * vec3(cos(6.28318*(x + 0.00)), cos(6.28318*(x + 0.33)), cos(6.28318*(x + 0.66)));
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec4 base = Texel(tex, tc);
  float a = base.a * color.a * clamp(u_alpha, 0.0, 1.0);
  if (a <= 0.0) return vec4(0.0);
  float phase = u_time * u_speed + dot(tc, u_dir) * u_scale;
  vec3 col = rainbow(phase);
  return vec4(col, a);
}

extern vec2   u_texSize;   // texture size in pixels
extern number u_strength;  // 0..1
extern vec3   u_color;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc);
  float a = px.a * color.a;
  if (a < 0.1) discard;

  vec2 stepUV = vec2(1.0 / max(u_texSize.x, 1.0), 1.0 / max(u_texSize.y, 1.0));

  // Sample alpha in 4-neighborhood
  float aL = Texel(tex, tc + vec2(-stepUV.x, 0.0)).a;
  float aR = Texel(tex, tc + vec2( stepUV.x, 0.0)).a;
  float aU = Texel(tex, tc + vec2(0.0, -stepUV.y)).a;
  float aD = Texel(tex, tc + vec2(0.0,  stepUV.y)).a;

  float minN = min(min(aL, aR), min(aU, aD));

  // Inner edge factor: strong when current pixel is solid but neighbor is transparent
  float edge = clamp((a - minN) * 10.0, 0.0, 1.0);
  edge = pow(edge, 1.2);

  float outA = edge * clamp(u_strength, 0.0, 1.0);
  if (outA <= 0.001) discard;

  return vec4(u_color, outA);
}

extern vec3 u_tint;
extern number u_alpha;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float a = Texel(tex, tc).a * color.a * clamp(u_alpha, 0.0, 2.0);
  return vec4(u_tint, a);
}

extern vec4 u_frameUV;   // {minU,minV,sizeU,sizeV}
extern vec2 u_framePx;   // {frameW, frameH} in pixels
extern vec2 u_centerPx;  // center within frame in pixels
extern float u_u;
extern vec4 u_sparkColor;

float lineDist(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 texColor = Texel(tex, tc);
  if (texColor.a < 0.1) discard;

  // Normalize into the quad's local UV (0..1)
  vec2 tcL = tc;
  if (u_frameUV.z > 0.0 && u_frameUV.w > 0.0){
    tcL = (tc - u_frameUV.xy) / u_frameUV.zw;
    tcL = clamp(tcL, 0.0, 1.0);
  }
  // Convert into local pixel coords within the frame
  vec2 p = vec2(tcL.x * u_framePx.x, tcL.y * u_framePx.y);

  // Sizes in SPRITE-PIXEL units (stable under scaling/canvases)
  float r1 = 1.0;
  float r2 = (3.0 + 4.0 * u_u);
  float thickness = 0.6;

  float sparkAlpha = 0.0;

  // 1. Center Flash
  float d = length(p - u_centerPx);
  if (d < 1.5 * (1.0 - u_u)) {
    sparkAlpha = 0.4;
  }

  // 2. 4 Lines
  for(int i=0; i<4; i++) {
    float angle = (float(i) / 4.0) * 6.28318 + (u_u * 0.3);
    vec2 p1 = u_centerPx + vec2(cos(angle), sin(angle)) * r1;
    vec2 p2 = u_centerPx + vec2(cos(angle), sin(angle)) * r2;
    if (lineDist(p, p1, p2) < thickness) {
      sparkAlpha = 1.0;
    }
  }

  if (sparkAlpha > 0.0) {
    float outA = sparkAlpha * u_sparkColor.a * color.a;
    return vec4(u_sparkColor.rgb, outA);
  }
  discard;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  if (Texel(tex, tc).a < 0.1) discard;
  return vec4(1.0);
}

extern number u_intensity;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc);
  return vec4(1.0, 1.0, 1.0, px.a * u_intensity) * color;
}

extern number u_cutoff;
extern vec3 u_tint;
extern number u_seed;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc) * color;
  if (px.a <= 0.001) { return vec4(0.0); }
  // Cheap hash noise based on texture coord and seed
  float n = fract(sin(dot(tc * vec2(127.1, 311.7) + float(u_seed), vec2(269.5,183.3))) * 43758.5453);
  // Mask: remove pixels below cutoff
  float keep = step(float(u_cutoff), n);
  // Edge glow near cutoff
  float glow = smoothstep(float(u_cutoff) - 0.07, float(u_cutoff), n) * (1.0 - smoothstep(float(u_cutoff), float(u_cutoff) + 0.05, n));
  vec3 rgb = mix(u_tint, px.rgb, 1.0 - glow);
  float alpha = px.a * keep + glow * 0.7;
  return vec4(rgb, alpha);
}

extern float u_time;
extern float u_targetDpi;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec2 logicalSc = sc / max(1.0, u_targetDpi);
  float p = (logicalSc.x * 0.06 + logicalSc.y * 0.04) + u_time * 1.5;
  float r = 0.70 + 0.30 * sin(p + 0.0);
  float g = 0.65 + 0.35 * sin(p + 2.1);
  float b = 0.75 + 0.25 * sin(p + 4.2);
  return vec4(r, g, b, color.a);
}

extern float u_progress;
extern float u_envelope;
extern float u_alpha;
extern vec2 u_textureSize;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc);
  if (px.a <= 0.01) return vec4(0.0);
  vec2 p = tc * u_textureSize;
  float bandWidth = 20.0;
  float shineX = -bandWidth + (u_textureSize.x + bandWidth * 2.0) * u_progress;
  float localX = cos(0.5) * (p.x - shineX) - sin(0.5) * (p.y - u_textureSize.y * 0.5);
  float wide = 1.0 - smoothstep(bandWidth * 0.34, bandWidth * 0.52, abs(localX));
  float core = 1.0 - smoothstep(bandWidth * 0.055, bandWidth * 0.13, abs(localX));
  float strength = clamp(wide * 0.58 + core * 0.42, 0.0, 1.0);
  vec3 shine = mix(vec3(1.0, 0.86, 0.38), vec3(1.0, 1.0, 0.96), core);
  return vec4(shine, px.a * strength * u_envelope * u_alpha) * color;
}

